use crate::{catalog,model::*,rules::*,unit_support::*};
fn setup(core:&str)->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let c=g.make_card(core,0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:core.into(),card:Some(c),rest:2});fund(&mut g,0,"BQ064",14);g.add_society_markers(0,0,1);g}
fn play(g:&mut Game)->String{let id=held(g,"BQ065",0);act(g,0,Action{card_id:Some(id),target_id:Some("society:p0".into()),option:Some("secret-plan".into()),..Action::new("play")});crate::jc029_tests::pass_top(g);g.attachments.iter().find(|a|a.card.definition=="BQ065").unwrap().card.id.clone()}
fn choose(g:&mut Game,ids:Vec<String>){let p=g.pending.clone().unwrap();act(g,p.seat,Action{choice_id:Some(p.choice.id),selected:Some(ids),..Action::new("choose")});}
fn ready(g:&mut Game,id:&str){let n=g.plan_threshold(&g.attachments.iter().find(|a|a.card.id==id).unwrap().card).unwrap();for _ in 0..n {act(g,0,Action{card_id:Some(id.into()),ability_id:Some(crate::batch4_plans::ADVANCE.into()),..Action::new("activate")});crate::jc029_tests::pass_top(g);if g.pending.is_some(){break;}}}
#[test]fn bq065_printed_threshold_core_entry_and_optional_extra_shield(){for core in ["BQ045","BQ046"]{for shield in [false,true]{let mut g=setup(core);let id=play(&mut g);assert!(!catalog::card("BQ065").supported);assert!(g.attachments[0].card.face_down);ready(&mut g,&id);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq065-region");restore(&mut g);choose(&mut g,vec!["region:1".into()]);crate::jc029_tests::pass_top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq065-shield");restore(&mut g);choose(&mut g,if shield{vec!["shield".into()]}else{vec![]});while !g.effects.is_empty()||!g.stack.is_empty(){crate::jc029_tests::pass_top(&mut g);}let c=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition==core).unwrap();assert_eq!(c.shield,u32::from(shield)+u32::from(core=="BQ045"));assert!(g.core_zones[0].card.is_none());assert_eq!(g.core_zones[0].rest,2);assert!(g.players[0].graveyard.iter().any(|c|c.definition=="BQ065"));restore(&mut g);}}}
fn invalid(g:&Game,bad:&Game){assert!(Game::from_persisted(&serde_json::to_string(bad).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=bad.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq065_target_and_shield_restore_cannot_be_optional_transplanted_or_duplicated(){let mut g=setup("BQ046");let id=play(&mut g);ready(&mut g,&id);for n in 0..4{let mut b=g.clone();match n{0=>b.pending=None,1=>b.pending.as_mut().unwrap().choice.min=Some(0),2=>b.pending.as_mut().unwrap().seat=1,_=>{let ChoiceResolution::Declare{declaration,..}=&b.pending.as_ref().unwrap().resolution else{panic!()};b.effects.push_back(Effect::Declare{declaration:declaration.clone()});}}invalid(&g,&b);}choose(&mut g,vec!["region:1".into()]);crate::jc029_tests::pass_top(&mut g);for n in 0..4{let mut b=g.clone();let p=b.pending.as_mut().unwrap();match n{0=>p.choice.options.clear(),1=>p.seat=1,_=>{let ChoiceResolution::Frame{frame,choice:FrameChoice::BQ065Shield{card_id}}=&mut p.resolution else{panic!()};if n==2{*card_id=frame.source.card.id.clone();}else{b.effects.push_back(Effect::Frame{frame:frame.clone()});}}}invalid(&g,&b);}restore(&mut g);}
#[test]fn bq065_region_replacement_and_core_outside_zone_do_not_redirect(){for mode in 0..2{let mut g=setup("BQ046");let id=play(&mut g);ready(&mut g,&id);choose(&mut g,vec!["region:1".into()]);if mode==0{g.regions[1].card=g.make_card("DQJC115",0);}else{let c=g.core_zones[0].card.take().unwrap();g.regions[0].cards.push(c);}crate::jc029_tests::pass_top(&mut g);assert!(g.pending.is_none());assert!(!g.regions[1].cards.iter().any(|c|c.definition=="BQ046"));assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="BQ065").count(),usize::from(mode==1));restore(&mut g);}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn select(g:&Game,p:&Pending,shield:bool)->Vec<String>{if p.choice.kind=="bq065-region"{return vec!["region:1".into()];}if p.choice.kind=="bq065-shield"{return if shield{vec!["shield".into()]}else{vec![]};}let mut options=p.choice.options.iter().collect::<Vec<_>>();options.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"BQ065"|"BQ064")));options.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{use crate::{deck,abi112_review_play_tests::Trace};fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="bq065-natural-50-plus-core".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some("BQ046".into());d.cards=[("BQ065",3),("BQ064",3),("BQ048",3),("BQ050",3),("BQ063",3),("JC125",35)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ065","BQ046","BQ048","BQ050","BQ063"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq065".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
 let(seed,g)=(1..1025).find_map(|seed|{let g=construct(seed);["BQ065","BQ064","JC125"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)).then_some((seed,g))}).expect("actual dealt plan and gray asset");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"bq065-natural-fifty-plus-core-plan-release".into(),760);let mut done=false;for _ in 0..1400{if let Some(p)=t.room.game.pending.clone(){let end=p.choice.kind=="bq065-shield";let ids=select(&t.room.game,&p,true);t.choose(ids);if end{done=true;}continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let plan=g.attachments.iter().find(|a|a.card.definition=="BQ065");let a=if g.players[0].assets.len()<4{let wanted=if g.players[0].assets.is_empty(){"BQ064"}else{"JC125"};legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==wanted)))}else if let Some(plan)=plan{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::batch4_plans::ADVANCE)&&a.action.card_id.as_deref()==Some(&plan.card.id))}else if !done{legal.iter().find(|a|a.action.kind=="play"&&a.action.option.is_none()&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ065")))}else{None};if let Some(a)=a{t.action(0,a.action.clone());}else{t.pass();}}
 assert!(done);assert!(t.room.game.core_zones[0].card.is_none());assert!(t.room.game.regions[1].cards.iter().any(|c|c.definition=="BQ046"&&c.shield==1));let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"separateCore":1,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn bq065_natural_and_prepared_native_export(){use crate::abi112_review_play_tests::Trace;let mut cases=vec![natural()];for(shield,index)in[(false,761),(true,762)]{let mut g=setup("BQ045");let id=play(&mut g);ready(&mut g,&id);let mut t=Trace::new_preserving_rng(g,format!("bq065-prepared-shield-{shield}"),index);for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){let ids=select(&t.room.game,&p,shield);t.choose(ids);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert_eq!(t.room.game.regions[1].cards.iter().find(|c|c.definition=="BQ045").unwrap().shield,1+u32::from(shield));cases.push(duplicate(t.value()));}let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq065.rs",include_bytes!("bq065.rs").as_slice()),("rust-game/src/bq065_tests.rs",include_bytes!("bq065_tests.rs").as_slice()),("rust-game/src/batch4_plans.rs",include_bytes!("batch4_plans.rs").as_slice()),("rust-game/src/core_zone.rs",include_bytes!("core_zone.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(path)=std::env::var("BQ065_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn bq065_cancelled_target_receipt_survives_restore_and_clears_on_plan_departure(){let mut g=setup("BQ046");let id=play(&mut g);ready(&mut g,&id);choose(&mut g,vec!["region:1".into()]);for n in 0..3{let mut b=g.clone();let f=b.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.targets[0].region_instance=None,1=>f.targets[0].public.region=Some(0),_=>f.targets[0].id="region:99".into()}invalid(&g,&b);}g.regions[1].card=g.make_card("DQJC115",0);crate::jc029_tests::pass_top(&mut g);assert_eq!(g.bq065_cancelled.len(),1);restore(&mut g);let mut b=g.clone();b.bq065_cancelled.clear();invalid(&g,&b);let mut b=g.clone();b.bq065_cancelled.push(b.bq065_cancelled[0].clone());invalid(&g,&b);g.remove_dead(&id,RemovalCause::Destroy);g.drive().unwrap();assert!(g.bq065_cancelled.is_empty());restore(&mut g);}
#[test]fn bq065_wrong_actor_and_secret_without_moon_are_rejected(){let mut g=setup("BQ046");g.players[0].society_zone.secrecy=0;let id=held(&mut g,"BQ065",0);reject(&mut g,0,Action{card_id:Some(id.clone()),target_id:Some("society:p0".into()),option:Some("secret-plan".into()),..Action::new("play")});reject(&mut g,0,Action{card_id:Some(id.clone()),target_id:Some("society:p1".into()),..Action::new("play")});act(&mut g,0,Action{card_id:Some(id),target_id:Some("society:p0".into()),..Action::new("play")});crate::jc029_tests::pass_top(&mut g);let id=g.attachments[0].card.id.clone();reject(&mut g,1,Action{card_id:Some(id),ability_id:Some(crate::batch4_plans::ADVANCE.into()),..Action::new("activate")});restore(&mut g);}
